import { test } from "node:test";
import assert from "node:assert/strict";
import { AppError, errorChain, isRetryable, toLogRecord, wrap } from "../src/shipping/errors.ts";
import { CarrierAdapter, TransportError, type HttpResponse, type Transport } from "../src/shipping/carrier.ts";
import { LabelService, buyWave, type Shipment } from "../src/shipping/labels.ts";

// A carrier API that answers with the given responses in order (the last one repeats).
function scripted(...responses: HttpResponse[]): Transport & { calls: number } {
    const t = {
        calls: 0,
        async post() {
            return responses[Math.min(t.calls++, responses.length - 1)];
        },
    };
    return t;
}

const ok = (trackingNumber: string): HttpResponse => ({ status: 201, headers: {}, body: { trackingNumber } });
const fail = (status: number, requestId: string, extra: HttpResponse["body"] = {}): HttpResponse => ({
    status,
    headers: { "x-request-id": requestId },
    body: { error: "carrier says no", ...extra },
});

const shipment = (id: string, carrier: string): Shipment => ({
    id,
    orderId: `ord-${id}`,
    carrier,
    parcel: { weightGrams: 1200, fromPostcode: "10115", toPostcode: "80331" },
});

test("a label is bought from the shipment's carrier", async () => {
    const service = new LabelService([new CarrierAdapter("dhl", scripted(ok("JD0001")))]);
    assert.deepEqual(await service.buy(shipment("s1", "dhl")), { carrier: "dhl", trackingNumber: "JD0001" });
});

test("a carrier outage is retried and the label still bought", async () => {
    const transport = scripted(fail(503, "r1"), fail(429, "r2"), ok("JD0002"));
    const service = new LabelService([new CarrierAdapter("dhl", transport)]);
    assert.equal((await service.buy(shipment("s2", "dhl"))).trackingNumber, "JD0002");
    assert.equal(transport.calls, 3);
});

test("a rejected parcel is not retried and keeps its code", async () => {
    const transport = scripted(fail(422, "r9", { field: "to_postcode" }));
    const service = new LabelService([new CarrierAdapter("ups", transport)]);
    await assert.rejects(service.buy(shipment("s3", "ups")), (err: unknown) => {
        assert.ok(err instanceof AppError);
        assert.equal(err.code, "parcel_rejected");
        assert.equal(isRetryable(err), false);
        return true;
    });
    assert.equal(transport.calls, 1);
});

test("the log record for a failed label has the shipment's and the carrier's context", async () => {
    const service = new LabelService([new CarrierAdapter("ups", scripted(fail(503, "ups-req-77")))], 2);
    const err = await service.buy(shipment("s4", "ups")).catch((e: unknown) => e);
    const record = toLogRecord(err);
    console.log("log record:", JSON.stringify(record, null, 2));
    assert.equal(record.code, "carrier_unavailable");
    assert.deepEqual(record.context, { carrier: "ups", httpStatus: 503, carrierRequestId: "ups-req-77", shipmentId: "s4", orderId: "ord-s4", attempts: 2 });
});

test("the cause chain keeps every layer down to the HTTP error", async () => {
    const service = new LabelService([new CarrierAdapter("ups", scripted(fail(422, "r5", { field: "weight_g" })))]);
    const err = await service.buy(shipment("s5", "ups")).catch((e: unknown) => e);
    const chain = errorChain(err);
    assert.equal(chain.length, 3, `chain: ${chain.map((e) => (e as Error).message).join("  <-  ")}`);
    assert.equal((chain[1] as AppError).context.field, "weight_g");
    assert.ok(chain[2] instanceof TransportError);
    assert.equal(chain[2].status, 422);
});

test("the wave report names the carrier of every failed shipment", async () => {
    const service = new LabelService([
        new CarrierAdapter("dhl", scripted(ok("JD0100"))),
        new CarrierAdapter("ups", scripted(fail(400, "u1"))),
        new CarrierAdapter("fedex", scripted(fail(422, "f1", { field: "from_postcode" }))),
    ]);
    const report = await buyWave(service, "wave-12", [shipment("a", "dhl"), shipment("b", "ups"), shipment("c", "fedex")]);
    assert.deepEqual(report.labels.map((l) => l.trackingNumber), ["JD0100"]);
    assert.deepEqual(report.failures.map((f) => [f.shipmentId, f.code, f.carrier]), [["b", "carrier_error", "ups"], ["c", "parcel_rejected", "fedex"]]);
    assert.equal(report.failures[1].log.context.shipmentId, "c");
    assert.equal(report.failures[1].log.context.waveId, "wave-12");
});

test("wrapping a plain error keeps it as the cause", () => {
    const root = new Error("socket hang up");
    const err = wrap(root, "label for shipment s6", { shipmentId: "s6" });
    assert.equal(err.message, "label for shipment s6: socket hang up");
    assert.equal(err.code, "internal");
    assert.equal(err.cause, root);
    assert.deepEqual(toLogRecord(err).causes, ["Error: socket hang up"]);
});
